BJ = '"Bujin"'
BWB = 'monstruo ' + BJ + ' de Tipo Bestia-Guerrero'
def only(n): return ' Sólo puedes controlar 1 "%s".' % n
def oncef(n): return ' Sólo puedes usar el efecto de "%s" una vez por turno.' % n
ES = {
"Bujin Arasuda": 'Si un monstruo ' + BJ + ' en tu Cementerio o boca arriba en tu lado del Campo es desterrado (excepto durante el Damage Step): puedes Invocar esta carta de Modo Especial desde tu mano en Posición de Defensa boca arriba. Una vez por turno, durante la End Phase, si este turno se añadió a tu mano desde tu Deck una carta ' + BJ + ', excepto robándola, mientras controlabas esta carta boca arriba: puedes robar 1 carta y, después, descartar 1 carta.' + only("Bujin Arasuda"),
"Bujin Hirume": 'No puede ser Invocada de Modo Normal ni Colocada. Primero debe ser Invocada de Modo Especial (desde tu mano) desterrando 1 monstruo ' + BJ + ' de tu Cementerio, excepto "Bujin Hirume". Si esta carta, que fue Invocada de esta forma, es destruida por una carta de tu adversario (en batalla o por un efecto de carta), y mandada de tu lado del Campo a tu Cementerio, y ambos jugadores tienen mano: puedes descartar 1 carta y, después, tu adversario descarta 1 carta.' + only("Bujin Hirume"),
"Bujin Mahitotsu": 'Puedes mandar 1 otra carta ' + BJ + ' de tu mano al Cementerio; Invoca esta carta de Modo Especial desde tu mano. Puedes activar 1 de estos efectos;\n● Manda 1 monstruo ' + BJ + ' de tu mano al Cementerio; añade a tu mano 1 monstruo ' + BJ + ' con un nombre distinto de tu Cementerio.\n● Destierra 1 monstruo ' + BJ + ' de tu Cementerio; manda al Cementerio 1 monstruo ' + BJ + ' con un nombre distinto de tu Deck.\nSólo puedes usar el efecto de Invocación, y el otro efecto, de "Bujin Mahitotsu" una vez por turno cada uno.',
"Bujin Mikazuchi": 'Cuando uno o más monstruos ' + BJ + ' de Tipo Bestia-Guerrero que controlas sean destruidos en batalla o por un efecto de carta y mandados al Cementerio: puedes Invocar esta carta de Modo Especial desde tu mano. Una vez por turno, durante la End Phase, si uno o más monstruos ' + BJ + ' fueron mandados de tu mano a tu Cementerio este turno mientras controlabas esta carta boca arriba: puedes añadir a tu mano 1 Carta Mágica/de Trampa ' + BJ + ' de tu Deck.' + only("Bujin Mikazuchi"),
"Bujin Torifune": 'Puedes Sacrificar esta carta; Invoca de Modo Especial desde el Deck 2 monstruos ' + BJ + ' de 2 Tipos distintos en Posición de Defensa, excepto "Bujin Torifune". Cuando Invoques por Xyz un Monstruo Xyz ' + BJ + ', mientras esta carta está en tu Cementerio: puedes equiparle esta carta. Cualquier monstruo destruido en batalla con ese monstruo equipado es desterrado. Sólo puedes usar cada efecto de "Bujin Torifune" una vez por turno.',
"Bujin Yamato": 'Una vez por turno, durante tu End Phase: puedes añadir a tu mano 1 monstruo ' + BJ + ' de tu Deck y, después, mandar 1 carta de tu mano al Cementerio.' + only("Bujin Yamato"),
"Bujingi Boar": 'Si controlas un monstruo ' + BJ + ': puedes desterrar esta carta de tu Cementerio y, después, seleccionar 1 monstruo boca arriba en Posición de Ataque que controle tu adversario; cámbialo a Posición de Defensa boca arriba y, si lo haces, su DEF pasa a ser 0 hasta el final de este turno.',
"Bujingi Centipede": 'Si controlas un ' + BWB + ': puedes desterrar esta carta de tu Cementerio y, después, seleccionar 1 Carta Mágica/de Trampa que controle tu adversario; destruye ese objetivo.' + oncef("Bujingi Centipede"),
"Bujingi Crane": 'Durante el cálculo de daño (en el turno de cualquier jugador), si un ' + BWB + ' que controlas combate con un monstruo de tu adversario: puedes mandar esta carta de tu mano al Cementerio; el ATK de tu monstruo pasa a ser el doble de su ATK original, sólo durante ese cálculo de daño.',
"Bujingi Crow": 'Cuando un ' + BWB + ' que controlas sea elegido como objetivo de un ataque de un monstruo de tu adversario: puedes mandar esta carta de tu mano al Cementerio; niega el ataque y, si lo haces, inflige a tu adversario daño igual a la mitad del ATK del atacante.' + oncef("Bujingi Crow"),
"Bujingi Fox": 'Durante el turno de cualquier jugador: puedes desterrar esta carta de tu Cementerio y mandar 1 monstruo ' + BJ + ' de tu mano al Cementerio; no recibes daño este turno.',
"Bujingi Hare": 'Durante el turno de cualquier jugador: puedes desterrar esta carta de tu Cementerio y, después, seleccionar 1 ' + BWB + ' que controles; una vez durante este turno, no puede ser destruido en batalla ni por efectos de cartas.' + oncef("Bujingi Hare"),
"Bujingi Ibis": 'Durante tu Main Phase 1: puedes mandar esta carta de tu mano al Cementerio y, después, seleccionar 1 monstruo ' + BJ + ' que controles; este turno, si ataca a un monstruo en Posición de Defensa, inflige daño de batalla de penetración a tu adversario.',
"Bujingi Ophidian": 'Durante tu Main Phase 1: puedes mandar esta carta de tu mano al Cementerio y, después, seleccionar 1 monstruo ' + BJ + ' que controles; puede atacar directamente a tu adversario este turno.',
"Bujingi Pavo": 'Cuando un ' + BWB + ' que controlas sea destruido en batalla y mandado al Cementerio: puedes mandar esta carta de tu mano al Cementerio; Invoca de Modo Especial 1 monstruo ' + BJ + ' de tu Deck.' + oncef("Bujingi Pavo"),
"Bujingi Peacock": 'Durante tu Main Phase 2: puedes mandar esta carta de tu mano al Cementerio; añade a tu mano 1 monstruo ' + BJ + ' de tu Deck. No puedes activar cartas ni efectos el turno en que actives este efecto, excepto cartas ' + BJ + '.' + oncef("Bujingi Peacock"),
"Bujingi Quilin": 'Si controlas un ' + BWB + ': puedes desterrar esta carta de tu Cementerio y, después, seleccionar 1 carta boca arriba que controle tu adversario; destruye ese objetivo.' + oncef("Bujingi Quilin"),
"Bujingi Raven": 'Cuando un monstruo ' + BJ + ' que controlas sea destruido en batalla con un monstruo de tu adversario y mandado a tu Cementerio: puedes mandar esta carta de tu mano al Cementerio; destruye ese monstruo de tu adversario.',
"Bujingi Sinyou": 'Durante el Damage Step de cualquier jugador, si un ' + BWB + ' que controlas combate con un monstruo de tu adversario: puedes desterrar esta carta de tu Cementerio; ese monstruo que controlas gana ATK igual al ATK actual del monstruo de tu adversario con el que combate hasta el final del Damage Step y, si lo hace, todo el daño de batalla que reciba tu adversario de esa batalla se reduce a la mitad. Sólo puedes usar este efecto de "Bujingi Sinyou" una vez por turno.',
"Bujingi Swallow": 'Durante tu Main Phase 1: puedes mandar esta carta de tu mano al Cementerio y, después, seleccionar 1 monstruo ' + BJ + ' que controles; puede realizar un segundo ataque durante cada Battle Phase este turno. Los demás monstruos no pueden atacar durante el turno en que actives este efecto.',
"Bujingi Turtle": 'Durante el turno de cualquier jugador, cuando se active una carta o efecto que seleccione un monstruo ' + BJ + ' que controles (excepto durante el Damage Step): puedes desterrar esta carta de tu Cementerio; niega ese efecto.',
"Bujingi Warg": 'Mientras esta carta esté en Posición de Defensa boca arriba, los demás monstruos ' + BJ + ' que controlas no pueden ser destruidos por efectos de cartas.',
"Bujingi Wolf": 'Los demás monstruos de Tipo Bestia, Bestia-Guerrero y Bestia Alada que controlas no pueden ser destruidos en batalla.',
"Bujin Regalia - The Mirror": 'Al inicio de tu Main Phase 1, si tu adversario controla más monstruos que tú y tú controlas un ' + BWB + ': hasta el final del próximo turno de tu adversario, no se pueden activar Cartas Mágicas/de Trampa ni sus efectos.',
"Bujincandescence": 'Los monstruos ' + BJ + ' de Tipo Bestia-Guerrero que controlas no pueden ser destruidos por efectos de cartas de tu adversario, excepto durante la Battle Phase. Una vez por turno: puedes mandar al Cementerio 1 monstruo ' + BJ + ' de tu mano o Campo boca arriba y, después, seleccionar 1 carta boca arriba que controle tu adversario; niega sus efectos hasta el final de este turno. Durante tu End Phase: puedes mandar esta carta boca arriba del Campo al Cementerio y, después, seleccionar 1 monstruo ' + BJ + ' en tu Cementerio; Invócalo de Modo Especial.',
"Bujincarnation": 'Si tu adversario controla un monstruo y tú no controlas monstruos: selecciona 1 monstruo ' + BJ + ' en tu Cementerio y 1 de tus monstruos ' + BJ + ' desterrados; Invoca de Modo Especial ambos objetivos. No pueden ser usados como Material Xyz para una Invocación por Xyz, excepto para la Invocación por Xyz de un monstruo de Tipo Bestia, Bestia-Guerrero o Bestia Alada.',
"Bujintervention": 'Selecciona 1 monstruo ' + BJ + ' en el Campo; aplícale este efecto durante el resto de este turno. Cada vez que destruya en batalla un monstruo cuyo ATK actual sea mayor o igual que el ATK original del monstruo seleccionado, y lo mande al Cementerio: destierra el monstruo destruido y, si lo haces, destierra todos los monstruos de la mano, Deck Principal, Extra Deck y Cementerio de tu adversario con el mismo nombre que tenía el monstruo destruido en el Cementerio.',
"Bujinunity": 'Si no controlas otras cartas y tienes al menos 1 otra carta en tu mano: baraja en el Deck todos los monstruos ' + BJ + ' de Tipo Bestia-Guerrero de tu Cementerio (mín. 1) y, si lo haces, manda toda tu mano al Cementerio (mín. 1) y, después, puedes añadir a tu mano hasta 3 monstruos ' + BJ + ' de Tipo Bestia-Guerrero con nombres distintos de tu Deck. Sólo puedes activar 1 "Bujinunity" por turno.',
"Bujin Regalia - The Jewel": 'Selecciona 1 Monstruo Xyz de Rango 4 que controles; equipa esta carta a ese objetivo. Gana 300 ATK por cada Material Xyz acoplado a él. Una vez por turno, mientras esta carta esté equipada a un monstruo por este efecto: puedes acoplar 1 monstruo ' + BJ + ' de tu mano al monstruo equipado como Material Xyz.',
"Bujin Regalia - The Sword": 'Activa 1 de estos efectos.\n● Selecciona 1 monstruo ' + BJ + ' en tu Cementerio; añade ese objetivo a tu mano.\n● Selecciona 1 de tus monstruos ' + BJ + ' desterrados; devuelve ese objetivo al Cementerio.',
"Bujincident": 'Selecciona 1 Monstruo Xyz ' + BJ + ' que controles; destiérralo y, si lo haces, devuelve todos los monstruos en el Campo a la mano. Hasta tu 2ª End Phase después de la activación, ningún jugador puede Invocar monstruos ni recibir daño (pero sí Colocar de Modo Normal). Durante tu 2ª End Phase después de la activación: selecciona 1 monstruo ' + BJ + ' en tu Cementerio; Invoca de Modo Especial el monstruo desterrado por este efecto y, si lo haces, acóplale ese objetivo como Material Xyz.',
"Bujinfidel": 'Sacrifica 1 ' + BWB + ' y, después, selecciona 1 monstruo ' + BJ + ' con un nombre distinto en tu Cementerio; Invoca de Modo Especial ese objetivo.',
"Bujinki Amaterasu": '3 monstruos de Nivel 4\nSólo puedes controlar 1 "Bujinki Amaterasu". Una vez por turno, durante el turno de cualquier jugador: puedes desacoplar 1 Material Xyz de esta carta; aplica este efecto, según de quién sea el turno.\n● Tu turno: selecciona 1 de tus monstruos desterrados de Nivel 4 o menor; Invoca de Modo Especial ese objetivo.\n● Turno de tu adversario: selecciona 1 de tus monstruos desterrados de Nivel 4 o menor; añade ese objetivo a tu mano.',
"Bujintei Kagutsuchi": '2 monstruos de Tipo Bestia-Guerrero de Nivel 4\nCuando esta carta sea Invocada por Xyz: manda al Cementerio las 5 cartas superiores de tu Deck (o todo tu Deck, si tiene menos de 5) y, además, esta carta gana 100 ATK por cada carta ' + BJ + ' mandada al Cementerio por este efecto. Si uno o más monstruos ' + BJ + ' de Tipo Bestia-Guerrero que controlas fueran a ser destruidos en batalla o por un efecto de carta, puedes desacoplar 1 Material Xyz de esta carta en lugar de destruir 1 de esos monstruos.' + only("Bujintei Kagutsuchi"),
"Bujintei Susanowo": '2 monstruos ' + BJ + ' de Nivel 4\nEsta carta puede atacar una vez a cada monstruo que controle tu adversario. Una vez por turno: puedes desacoplar 1 Material Xyz de esta carta; toma 1 monstruo ' + BJ + ' de tu Deck, y añádelo a tu mano o mándalo al Cementerio.' + only("Bujintei Susanowo"),
"Bujintei Tsukuyomi": '2 monstruos de LUZ de Nivel 4\nUna vez por turno: puedes desacoplar 1 material de esta carta; manda toda tu mano al Cementerio (mín. 1) y, si lo haces, roba 2 cartas. Cuando esta carta que controlabas boca arriba deje el Campo por un efecto de carta de tu adversario: puedes seleccionar monstruos ' + BJ + ' de Tipo Bestia-Guerrero de Nivel 4 en tu Cementerio, hasta el número de Materiales Xyz que tenía esta carta en el Campo; Invoca de Modo Especial esos objetivos.' + only("Bujintei Tsukuyomi"),
}
